for (const c of cases) {
  const r = applyPromotions(c.lines, c.promos, null, c.coupon || null);
  assert.equal(r.subtotal, c.expected.subtotal, c.name + ' subtotal');
  assert.equal(r.invoicePromoDisc, c.expected.invoicePromoDisc, c.name + ' invoicePromoDisc');
  assert.equal(r.couponDisc, c.expected.couponDisc, c.name + ' couponDisc');
  assert.deepEqual(r.lines.map((l) => l.net), c.expected.lineNets, c.name + ' nets');
  assert.deepEqual(r.lines.map((l) => l.promoDisc), c.expected.linePromoDisc, c.name + ' promoDisc');
  assert.deepEqual(r.lines.map((l) => l.promoNames), c.expected.promoNames, c.name + ' names');
}

assert.equal(r2(1.005), 1.01);
assert.equal(r2(-1.005), -1.01);
assert.equal(r2(2.675), 2.68);
// weekday filter: JS getDay() numbering (Sunday 0), same as the server
const sun = new Date(2026, 10, 29);   // 2026-11-29 is a Sunday
assert.equal(sun.getDay(), 0);
assert.equal(promoActive({ active: true, days: [0] }, sun), true);
assert.equal(promoActive({ active: true, days: [1] }, sun), false);
assert.equal(promoActive({ active: true, start: '2026-12-01' }, sun), false);
assert.equal(promoActive({ active: true, end: '2026-11-01' }, sun), false);
assert.equal(promoActive({ active: false }, sun), false);

console.log('promosLocal parity tests passed (' + cases.length + ' engine cases)');
